<?php $qty=(float)($_POST["qty"]??1);$price=(float)($_POST["price"]??0);$tax=(float)($_POST["tax"]??20);$subtotal=$qty*$price;$total=$subtotal*(1+$tax/100);?><!doctype html><meta name=viewport content="width=device-width"><style>body{font:16px system-ui;background:#f5f5f7;display:grid;place-items:center;min-height:100vh}.card{background:white;padding:32px;border-radius:24px;box-shadow:0 20px 60px #0001}input{display:block;margin:10px 0;padding:12px;border:1px solid #ddd;border-radius:10px}button{padding:12px 18px;background:#111;color:white;border:0;border-radius:10px}</style><div class=card><h1>Invoice Mini</h1><form method=post><input name=qty type=number value="<?=$qty?>" placeholder=Quantity><input name=price type=number step=.01 value="<?=$price?>" placeholder=Price><input name=tax type=number value="<?=$tax?>" placeholder="Tax %"><button>Calculate</button></form><p>Subtotal: ₺<?=number_format($subtotal,2)?></p><h2>Total: ₺<?=number_format($total,2)?></h2></div>